@main

fn produce(output chan int) {
    for value in 1:6 {
        output <- value
    }
}

fn square(input chan int, output chan int) {
    for i in 0:5 {
        value := <-input
        output <- value * value
    }
}

fn main() int {
    numbers := chan int{cap: 2}
    squares := chan int{cap: 2}
    xu produce(numbers)
    xu square(numbers, squares)
    for i in 0:5 {
        value := <-squares
        println(value)
    }
    << 0
}

@main

fn worker(id int, ch chan int) {
    println("协程 #" + str(id) + " 运行中...")
    ch <- id * 10
}

fn main() int {
    ch := chan int{cap: 3}
    // 使用 xu f() 并发启动轻量协程
    xu worker(1, ch)
    xu worker(2, ch)
    xu worker(3, ch)

    mut sum := 0
    for i in 0:3 {
        val := <-ch
        sum += val
    }
    println("汇总结果: " + str(sum))
    << 0
}

